import re

def node_by_title(doc, title):
    for node in doc["nodes"]:
        if node["title"] == title:
            return node
    return None

def scope_nodes(doc, scope_title):
    scope = node_by_title(doc, scope_title)
    if not scope:
        return []
    return [node_by_id(doc, nid) for nid in scope.get("children", [])]

def node_by_id(doc, node_id):
    for node in doc["nodes"]:
        if node["node_id"] == node_id:
            return node
    return None

def table_rows(node):
    if not node or node.get("kind") != "table":
        return []
    cols = node["table"]["columns"]
    rows = node["table"]["rows"]
    return [(i, {cols[j]: row[j] for j in range(len(cols))}) for i, row in enumerate(rows)]

def entities(doc, scope) -> list:
    # Products table: product, group, sub-group, storage location, kg per unit, opening stock
    prod_node = None
    for node in doc["nodes"]:
        if node["title"] == f"{scope}: Products":
            prod_node = node
            break

    if not prod_node:
        return []

    entities_list = []
    for _, row in table_rows(prod_node):
        entities_list.append({
            "id": row["product"],
            "description": row["product"]
        })
    return entities_list

def recorded_end(doc, scope) -> float or None:
    ledger_node = None
    for node in doc["nodes"]:
        if node["title"] == f"{scope}: Daily ledger":
            ledger_node = node
            break
    if not ledger_node:
        return None

    rows = table_rows(ledger_node)
    if not rows:
        return None

    # The last row's 'day' is the end of the period
    last_row = rows[-1][1]
    return float(last_row["day"])

def inputs(doc, scope) -> list:
    inputs_list = []

    # 1. Opening Stock from Products table
    prod_node = None
    for node in doc["nodes"]:
        if node["title"] == f"{scope}: Products":
            prod_node = node
            break
    if prod_node:
        for i, row in table_rows(prod_node):
            inputs_list.append({
                "id": f"opening_stock_{row['product']}",
                "time": 1.0, # Start of period
                "kind": "opening stock",
                "entities": [row["product"]],
                "fields": {"stock": float(row["opening stock"])},
                "src": [prod_node["node_id"], i]
            })

    # 2. Daily Production and Orders from Daily Ledger
    ledger_node = None
    for node in doc["nodes"]:
        if node["title"] == f"{scope}: Daily ledger":
            ledger_node = node
            break
    if ledger_node:
        for i, row in table_rows(ledger_node):
            day = float(row["day"])
            prod_id = row["product"]

            # Production
            produced = float(row["produced"])
            if produced > 0:
                inputs_list.append({
                    "id": f"prod_{day}_{prod_id}",
                    "time": day,
                    "kind": "production",
                    "entities": [prod_id],
                    "fields": {"quantity": produced},
                    "src": [ledger_node["node_id"], i]
                })

            # Orders
            ordered = float(row["ordered"])
            if ordered > 0:
                inputs_list.append({
                    "id": f"order_{day}_{prod_id}",
                    "time": day,
                    "kind": "order",
                    "entities": [prod_id],
                    "fields": {"quantity": ordered},
                    "src": [ledger_node["node_id"], i]
                })

    # 3. Order Book: Future inputs
    # Open orders at the end of the period (technically already inputs to the next period, 
    # but described as state here. The prompt asks for "records of future inputs").
    # Actually, the Order book tables specifically list planned production and orders.
    for node in doc["nodes"]:
        if node.get("kind") == "table" and "Order book: Orders received and production planned" in node["title"]:
            # Check if this table belongs to the current scope
            if node["parent_id"] == node_by_title(doc, scope)["node_id"] if node_by_title(doc, scope) else False:
                for i, row in table_rows(node):
                    day = float(row["day"])
                    prod_id = row["product"]

                    planned = float(row["planned production"])
                    if planned > 0:
                        inputs_list.append({
                            "id": f"future_prod_{day}_{prod_id}",
                            "time": day,
                            "kind": "planned production",
                            "entities": [prod_id],
                            "fields": {"quantity": planned},
                            "src": [node["node_id"], i]
                        })

                    ordered = float(row["ordered"])
                    if ordered > 0:
                        inputs_list.append({
                            "id": f"future_order_{day}_{prod_id}",
                            "time": day,
                            "kind": "planned order",
                            "entities": [prod_id],
                            "fields": {"quantity": ordered},
                            "src": [node["node_id"], i]
                        })

    return inputs_list

def outcomes(doc, scope) -> list:
    outcomes_list = []

    # 1. Ledger results: shipped, backordered, stock
    ledger_node = None
    for node in doc["nodes"]:
        if node["title"] == f"{scope}: Daily ledger":
            ledger_node = node
            break
    if ledger_node:
        for i, row in table_rows(ledger_node):
            day = float(row["day"])
            prod_id = row["product"]

            # Shipped
            shipped = float(row["shipped"])
            outcomes_list.append({
                "time": day,
                "kind": "shipped",
                "entities": [prod_id],
                "value": shipped,
                "src": [ledger_node["node_id"], i]
            })

            # Backordered
            backordered = float(row["backordered"])
            outcomes_list.append({
                "time": day,
                "kind": "backordered",
                "entities": [prod_id],
                "value": backordered,
                "src": [ledger_node["node_id"], i]
            })

            # Stock
            stock = float(row["stock"])
            outcomes_list.append({
                "time": day,
                "kind": "stock",
                "entities": [prod_id],
                "value": stock,
                "src": [ledger_node["node_id"], i]
            })

    # 2. Events list
    events_node = None
    for node in doc["nodes"]:
        if node["title"] == f"{scope}: Events":
            events_node = node
            break
    if events_node:
        for i, line in enumerate(events_node["lines"]):
            # Example: 'Day 29 (2023-01-29): SOP001L12P runs out of stock (236 units backordered).'
            match = re.search(r"Day (\d+)", line)
            if match:
                day = float(match.group(1))
                # Try to extract product if mentioned
                # Products are usually SOP... or SOS... (caps letters and numbers)
                prod_match = re.search(r"([A-Z0-9]{5,})", line)
                entities = [prod_match.group(1)] if prod_match else []

                outcomes_list.append({
                    "time": day,
                    "kind": "event",
                    "entities": entities,
                    "value": None,
                    "src": [events_node["node_id"], i]
                })

    return outcomes_list

def params(doc, scope) -> dict:
    # Extract dispatch capacity from the text node of the scope
    scope_node = node_by_title(doc, scope)
    if not scope_node or scope_node.get("kind") != "text":
        return {}

    text = scope_node["text"]
    # Example: 'Daily dispatch capacity: 300000\nkg.'
    match = re.search(r"Daily dispatch capacity: ([\d,]+)", text)
    if match:
        return {"daily_dispatch_capacity": float(match.group(1).replace(",", ""))}

    return {}

